import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {TodayProjectionDomainAdapter,TODAY_PROJECTION_STATES} from '../../../adapters/today/domain.js';
import {createBalanced6TodayProviders} from '../../../adapters/today/acceptance-data.js';
import {buildTodayOrchestrationViewModel,todayProjectionStateCopy} from '../../../surfaces/today/presentation.js';
import {CEP_PRODUCT_DESTINATION_REGISTRY} from '../../../foundation/global/shell/cep-destinations.js';

const rows=[];
const assert=(condition,message='assertion failed')=>{if(!condition)throw Error(message)};
const equal=(actual,expected,message='values differ')=>assert(actual===expected,`${message}: ${actual} !== ${expected}`);
const test=async(id,run)=>{try{rows.push({id,status:'PASS',detail:await run()})}catch(error){rows.push({id,status:'FAIL',error:String(error?.stack||error)})}};
const observedAt='2025-05-18T10:40:00Z';
const resolver={descriptor:()=>({providerId:'d07.test-only.resolver',authority:'TEST_ONLY_PRESENTATION_HARNESS'}),resolve:({destination,objectId})=>({state:'RESOLVABLE',destination,objectId,providerId:'d07.test-only.resolver',observedAt,resolutionRef:`d07:${destination}:${objectId}`})};
const populated=()=>new TodayProjectionDomainAdapter({providers:createBalanced6TodayProviders(),allowFixtureProviders:true,continuationResolver:resolver,allowFixtureResolvers:true});

await test('d07.normal-product-provider-unbound-is-unavailable',()=>{const adapter=new TodayProjectionDomainAdapter(),projection=adapter.project();equal(projection.state,'UNAVAILABLE');equal(projection.sources[0].reason,'TODAY_PROVIDER_UNBOUND');equal(projection.items.length,0);equal(projection.canonicalWrites,false);return {state:projection.state,reason:projection.sources[0].reason,items:0}});
await test('d07.normal-product-does-not-fabricate-session-recommendation-or-progress',()=>{const adapter=new TodayProjectionDomainAdapter(),projection=adapter.project(),vm=buildTodayOrchestrationViewModel(projection,{lang:'ar',adapter});assert(!vm.continuation&&!vm.recommendation&&vm.attention.length===0&&vm.recent.length===0&&vm.progress.length===0);assert(!vm.resumeAvailability.enabled);return {continuation:false,recommendation:false,attention:0,recent:0,progress:0,resumeEnabled:false}});
await test('d07.normal-product-copy-says-unavailable',()=>{const projection=new TodayProjectionDomainAdapter().project(),copy=todayProjectionStateCopy(projection,'en');assert(/unavailable/i.test(copy));return {copy}});
await test('d07.acceptance-provider-rejected-from-normal-product',()=>{const adapter=new TodayProjectionDomainAdapter({providers:createBalanced6TodayProviders()}),projection=adapter.project();equal(projection.state,'UNAVAILABLE');equal(projection.sources[0].reason,'TODAY_FIXTURE_PROVIDER_NOT_ADMITTED');return {state:projection.state,reason:projection.sources[0].reason}});
await test('d07.test-only-populated-harness-admits-all-presentation-kinds',()=>{const adapter=populated(),projection=adapter.project(),kinds=new Set(projection.items.map(item=>item.kind));equal(projection.state,'AVAILABLE_DATA');for(const kind of ['CONTINUE_SESSION','RECOMMENDATION','ATTENTION','RECENT_CONTEXT','PROGRESS'])assert(kinds.has(kind),`missing ${kind}`);equal(projection.items.length,16);return {classification:'TEST_ONLY_PRESENTATION_HARNESS__NOT_PRODUCT_PROVIDER_TRUTH',state:projection.state,itemCount:projection.items.length,kinds:[...kinds]}});
await test('d07.test-only-continuation-is-handoff-only',()=>{const adapter=populated(),projection=adapter.project(),continuation=projection.items.find(item=>item.kind==='CONTINUE_SESSION'),receipt=adapter.resume(continuation.id);assert(receipt.ok);equal(receipt.status,'CONTINUATION_READY');equal(receipt.mutated,false);equal(receipt.progressMutation,false);equal(receipt.masteryMutation,false);equal(receipt.accessDecisionMade,false);return {status:receipt.status,canonicalWrites:false,progressMutation:false,masteryMutation:false}});
await test('d07.greeting-day-context-derived-from-observation',()=>{const adapter=populated(),projection=adapter.project(),vm=buildTodayOrchestrationViewModel(projection,{lang:'ar',adapter});equal(vm.observedAt,observedAt);assert(vm.dayContext&&vm.dayContext!==vm.copy.noObservation);assert(vm.copy.greeting.includes('مرحب'));return {observedAt:vm.observedAt,dayContext:vm.dayContext,greeting:vm.copy.greeting}});
await test('d07.unavailable-day-context-never-invents-date',()=>{const adapter=new TodayProjectionDomainAdapter(),vm=buildTodayOrchestrationViewModel(adapter.project(),{lang:'en',adapter});equal(vm.observedAt,null);equal(vm.dayContext,vm.copy.noObservation);return {observedAt:null,dayContext:vm.dayContext}});
await test('d07.presentation-has-prominent-hero-and-explicit-rtl-spatial-order',()=>{const source=readFileSync(new URL('../../../surfaces/today/presentation.js',import.meta.url),'utf8');for(const token of ['today-eyebrow','today-day-context','today-session-visual','grid-template-areas: "main attention"','direction: ltr','overflow-wrap:anywhere'])assert(source.includes(token),`missing ${token}`);return {greeting:true,dayContext:true,hero:true,attentionRailRight:true,overflowBounded:true}});
await test('d07.presentation-responsive-probe-contract',()=>{const source=readFileSync(new URL('../../../surfaces/today/presentation.js',import.meta.url),'utf8');assert(source.includes('@media (max-width: 900px)'));assert(source.includes('grid-template-areas:"main" "attention"'));assert(source.includes('@media (max-width: 768px)'));return {wideTwoColumn:true,compactSingleColumn:true,sessionHeroStacks:true}});
await test('d07.stale-rescue-vocabulary-corrected',()=>{const s07=readFileSync(new URL('../../../tests/rescue/S07_W01_W02_SHELL_TODAY/s07-contracts.test.js',import.meta.url),'utf8'),cg3=readFileSync(new URL('../../../tests/rescue/CG3_W01_W02_COVERAGE/cg3-w01-w02-coverage.test.js',import.meta.url),'utf8');assert(!s07.includes("projection.state,'UNOBSERVED'"));assert(!cg3.includes("projection.state,'UNOBSERVED'"));assert(s07.includes("projection.state,'UNAVAILABLE'"));assert(cg3.includes("projection.state,'UNAVAILABLE'"));return {s07:'UNAVAILABLE',cg3:'UNAVAILABLE'}});
await test('d07.current-state-vocabulary-rejects-legacy-unobserved',()=>{assert(TODAY_PROJECTION_STATES.includes('UNAVAILABLE'));assert(!TODAY_PROJECTION_STATES.includes('UNOBSERVED'));return {states:TODAY_PROJECTION_STATES}});
await test('d07.shell-destination-count-remains-unfrozen',()=>{const descriptor=CEP_PRODUCT_DESTINATION_REGISTRY.descriptor();equal(descriptor.destinationCountFrozen,false);equal(descriptor.globalAreaBaselineCount,5);return {destinationCountFrozen:false,globalAreaBaselineCount:5,registeredCount:descriptor.count}});
await test('d07.reference-identity-matches-owner-confirmed-final',()=>{const bytes=readFileSync(new URL('../../../../cep-writer/references/visual/00_TODAY/CEP_TODAY_MAIN_ORCHESTRATION_REFERENCE.png',import.meta.url)),sha256=createHash('sha256').update(bytes).digest('hex');equal(sha256,'3f75eac759efd920cfb2600766c7719d1754359326bc5a3df5508bee864dd617');return {sha256,classification:'OWNER_CONFIRMED_FINAL_REFERENCE'}});
await test('d07.harness-label-is-explicit-and-test-only',()=>{const source=readFileSync(new URL('../../../../tools/d07-today-visual-harness.html',import.meta.url),'utf8');assert(source.includes('TEST_ONLY_PRESENTATION_HARNESS__NOT_PRODUCT_PROVIDER_TRUTH'));assert(source.includes('allowFixtureProviders:true'));assert(source.includes('normalProductProviderTruth'));return {classification:'TEST_ONLY_PRESENTATION_HARNESS__NOT_PRODUCT_PROVIDER_TRUTH',leaksIntoProduct:false}});

const fail=rows.filter(row=>row.status==='FAIL').length;
console.log(JSON.stringify({suite:'D07_TODAY_PRESENTATION_AUTHORITY',classification:'D07_PRESENTATION_CONVERGED__PRODUCT_PROVIDER_TRUTH_PRESERVED',pass:rows.length-fail,fail,rows},null,2));
if(fail)process.exitCode=1;
